r;\nimport java.util.function.LongUnaryOperator;\n\nclass Main {\n    static In in = new In();\n    static Out out = new Out();\n    static long mod = 1000000007;\n    static long inf = 0xfffffffffffffffL;\n\n    long[] fac, inv;\n    void solve() {\n        int n = in.nextInt();\n        int k = in.nextInt();\n\n        fac = new long[2 * n + 2];\n        inv = new long[2 * n + 2];\n        fac[0] = inv[0] = 1;\n        for (int i = 1; i < 2 * n + 2; i++) {\n            fac[i] = fac[i - 1] * i % mod;\n            inv[i] = powAndMod(fac[i], mod - 2);\n        }\n\n        if (n <= k) {\n            out.println(comb(n + n - 1, n));\n        } else {\n            long ans = 0;\n            for (int i = 0; i <= k; i++) {\n                ans = (ans + comb(n, i) * comb(n - 1, i) % mod) % mod;\n            }\n            out.println(ans);\n        }\n    }\n\n    long comb(int n, int r) {\n        return fac[n] * inv[r] % mod * inv[n - r] % mod;\n    }\n\n    static long powAndMod(long a, long b) {\n        long x = 1;\n        while (b > 0) {\n            if (b % 2 == 1) {\n                x = x * a % mod;\n                b--;\n            } else {\n                a = a * a % mod;\n                b /= 2;\n            }\n        }\n        return x;\n    }\n\n    public static void main(String[]$) {\n        new Main().solve();\n        out.flush();\n    }\n}\n\nclass In {\n    private BufferedReader reader = new BufferedReader(new InputStreamReader(System.in), 0x10000);\n    private StringTokenizer tokenizer;\n\n    String next() {\n        try {\n            while (tokenizer == null || !tokenizer.hasMoreTokens()) {\n                tokenizer = new StringTokenizer(reader.readLine());\n            }\n        } catch (IOException ignored) {\n        }\n        return tokenizer.nextToken();\n    }\n\n    int nextInt() {\n        return Integer.parseInt(next());\n    }\n\n    long nextLong() {\n        return Long.parseLong(next());\n    }\n\n    char[][] nextCharArray(int n, int m) {\n        char[][] a = new char[n][m];\n        for (int i = 0; i < n; i++) {\n            a[i] = next().toCharArray();\n        }\n        return a;\n    }\n\n    int[] nextIntArray(int n) {\n        int[] a = new int[n];\n        for (int i = 0; i < n; i++) {\n            a[i] = nextInt();\n        }\n        return a;\n    }\n\n    int[] nextIntArray(int n, IntUnaryOperator op) {\n        int[] a = new int[n];\n        for (int i = 0; i < n; i++) {\n            a[i] = op.applyAsInt(nextInt());\n        }\n        return a;\n    }\n\n    long[] nextLongArray(int n) {\n        long[] a = new long[n];\n        for (int i = 0; i < n; i++) {\n            a[i] = nextLong();\n        }\n        return a;\n    }\n\n    long[] nextLongArray(int n, LongUnaryOperator op) {\n        long[] a = new long[n];\n        for (int i = 0; i < n; i++) {\n            a[i] = op.applyAsLong(nextLong());\n        }\n        return a;\n    }\n}\n\nclass Out {\n    private static PrintWriter out = new PrintWriter(System.out);\n\n    void println(Object... a) {\n        StringJoiner joiner = new StringJoiner(\" \");\n        for (Object obj : a) {\n            joiner.add(String.valueOf(obj));\n        }\n        out.println(joiner);\n    }\n\n    void flush() {\n        out.flush();\n    }\n}\n','code','No abnormally found','Compile Error','Runtime Error','Memory Limit Exceeded','A',2),(603,'Given a code snippet below, which behavior most likely to occur when execute it?\nimport java.util.*;\n \npublic class Main {\n    public static void main(final String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] b = new int[n-1];\n        for (int i = 0; i < n-1; i++) {\n            b[i] = sc.nextInt();\n        }\n        \n        int count = b[0] + b[n-2];\n        for (int i = 0; i < n; i++) {\n            count += Math.min(b[i-1], b[i]);\n        }\n        System.out.println(count);\n        \n    }\n}','code','Internal error'