      for (int i = 0; i < n; i++) {\n            long a = in.nextLong();\n            long b = in.nextLong();\n\n            if (a == 0 && b == 0) {\n                zz++;\n            } else if (a == 0) {\n                az++;\n            } else if (b == 0) {\n                bz++;\n            } else {\n                long gcd = gcd(Math.abs(a), Math.abs(b));\n                a /= gcd;\n                b /= gcd;\n                if (a < 0 == b < 0) {\n                    pos.merge(new Pair(Math.abs(a), Math.abs(b)), 1, Integer::sum);\n                } else {\n                    neg.merge(new Pair(Math.abs(b), Math.abs(a)), 1, Integer::sum);\n                }\n            }\n        }\n        long ans = 1;\n        for (Map.Entry<Pair, Integer> entry : neg.entrySet()) {\n            if (pos.containsKey(entry.getKey())) {\n                int a = pos.get(entry.getKey());\n                int b = entry.getValue();\n                ans = ans * (((pow[a] + pow[b]) % mod + mod - 1) % mod) % mod;\n            } else {\n                int a = entry.getValue();\n                ans = ans * pow[a] % mod;\n            }\n        }\n        for (Map.Entry<Pair, Integer> entry : pos.entrySet()) {\n            if (!neg.containsKey(entry.getKey())) {\n                int a = entry.getValue();\n                ans = ans * pow[a] % mod;\n            }\n        }\n        ans = ans * (((pow[az] + pow[bz]) % mod + mod - 1) % mod) % mod;\n        ans = ans + zz;\n        out.println((ans + mod - 1) % mod);\n    }\n\n    long gcd(long a, long b) {\n        return 0 < b ? gcd(b, a % b) : a;\n    }\n\n    long lcm(long a, long b) {\n        return a / gcd(a, b) * b;\n    }\n\n    public static void main(String[]$) {\n        new Main().solve();\n        out.flush();\n    }\n}\n\nclass Pair {\n    long a;\n    long b;\n\n    public Pair(long a, long b) {\n        this.a = a;\n        this.b = b;\n    }\n\n    @Override\n    public boolean equals(Object o) {\n        if (this == o) {\n            return true;\n        }\n        if (o == null || getClass() != o.getClass()) {\n            return false;\n        }\n\n        Pair pair = (Pair)o;\n\n        if (a != pair.a) {\n            return false;\n        }\n        return b == pair.b;\n    }\n\n    @Override\n    public int hashCode() {\n        int result = (int)(a ^ (a >>> 32));\n        result = 31 * result + (int)(b ^ (b >>> 32));\n        return result;\n    }\n\n    @Override\n    public String toString() {\n        return \"Pair{\" + \"a=\" + a + \", b=\" + b + \'}\';\n    }\n}\n\nclass In {\n    private BufferedReader reader = new BufferedReader(new InputStreamReader(System.in), 0x10000);\n    private StringTokenizer tokenizer;\n\n    String next() {\n        try {\n            while (tokenizer == null || !tokenizer.hasMoreTokens()) {\n                tokenizer = new StringTokenizer(reader.readLine());\n            }\n        } catch (IOException ignored) {\n        }\n        return tokenizer.nextToken();\n    }\n\n    int nextInt() {\n        return Integer.parseInt(next());\n    }\n\n    long nextLong() {\n        return Long.parseLong(next());\n    }\n\n    char[][] nextCharArray(int n, int m) {\n        char[][] a = new char[n][m];\n        for (int i = 0; i < n; i++) {\n            a[i] = next().toCharArray();\n        }\n        return a;\n    }\n\n    int[] nextIntArray(int n) {\n        int[] a = new int[n];\n        for (int i = 0; i < n; i++) {\n            a[i] = nextInt();\n        }\n        return a;\n    }\n\n    int[] nextIntArray(int n, IntUnaryOperator op) {\n        int[] a = new int[n];\n        for (int i = 0; i < n; i++) {\n            a[i] = op.applyAsInt(nextInt());\n        }\n        return a;\n    }\n\n    long[] nextLongArray(int n) {\n        long[] a = new long[n];\n        for (int i = 0; i < n; i++) {\n            a[i] = nextLong();\n        }\n        return a;\n    }\n\n    long[] nextLongArray(int n, LongUnaryOperator op) {\n        long[] a = new long[n];\n        for (int i = 0; i < n; i++) {\n            a[i] = op.applyAsLong(nextLong());\n        }\n        return a;\n    }\n}\n\nclass Out {\n    private PrintWriter out = new PrintWriter(System.out);\n    boolean autoFlush = false;\n\n    void println(Object... a) {\n        StringJoiner joiner = new StringJoiner(\" \");\n        for (Object obj : a) {\n            joiner.add(String.valueOf(obj));\n        }\n        out.println(joiner);\n        if (autoFlush) {\n            out.flush();\n        }\n    }\n\n    void println(int[] a) {\n        StringJoiner joiner = new StringJoiner(\" \");\n        for (int i : a) {\n            joiner.add(Integer.toString(i));\n        }\n        out.println(joiner);\n        if (autoFlush) {\n            out.flush();\n        }\n    }\n\n    void println(long[] a) {\n        StringJoiner joiner = new StringJoiner(\" \");\n        for (long i : a) {\n            joiner.add(Long.toString(i));\n        }\n        out.println(joiner);\n        if (autoFlush) {\n            out.flush();\n        }\n    }\n\n    void flush() {\n        out.flush();\n    }\n}\n','code','Internal error','No abnormally found','Compile Error','Runtime Error','B',2),(1756,'Given a code snippet below, which behavior most likely to occur when execute it?\nimport java.util.*;\n\nclass Main{\n    public static void main(String[] args){\n        Scanner sc = new Scanner(System.in);\n        int H = sc.nextInt();\n        int W = sc.nextInt();\n        String[] dic = new String[H];\n        for(int i=0;i<H;i++) dic[i]=sc.next();\n        int end = -1;\n        for(int i=0;i<H;i++){\n          int left = 0;\n          while(dic[i].charAt(left)==\'.\') left++;\n          if(end>left){\n            System.out.println(\"Impossible\");\n            System.exit(0);\n          }\n          end = 4;\n          whlie(dic[i].charAt(end)==\'.\') end++;\n        }\n        System.out.println(\"Possible\");\n    }\n}\n','code','Time Limit Exceeded','Compile Er