    while ((c = read()) != -1) {\n            if (c == \'\\n\') break;\n            buf[cnt++] = (byte) c;\n        }\n        return new String(buf, 0, cnt);\n    }\n\n    public int nextInt() throws IOException {\n        int ret = 0;\n        byte c = read();\n        while (c <= \' \') c = read();\n        boolean neg = (c == \'-\');\n        if (neg) c = read();\n        do {\n            ret = ret * 10 + c - \'0\';\n        } while ((c = read()) >= \'0\' && c <= \'9\');\n        if (neg) return -ret;\n        return ret;\n    }\n\n    public long nextLong() throws IOException {\n        long ret = 0;\n        byte c = read();\n        while (c <= \' \') c = read();\n        boolean neg = (c == \'-\');\n        if (neg) c = read();\n        do {\n            ret = ret * 10 + c - \'0\';\n        } while ((c = read()) >= \'0\' && c <= \'9\');\n        if (neg) return -ret;\n        return ret;\n    }\n\n    public double nextDouble() throws IOException {\n        double ret = 0, div = 1;\n        byte c = read();\n        while (c <= \' \') c = read();\n        boolean neg = (c == \'-\');\n        if (neg) c = read();\n        do {\n            ret = ret * 10 + c - \'0\';\n        } while ((c = read()) >= \'0\' && c <= \'9\');\n        if (c == \'.\') while ((c = read()) >= \'0\' && c <= \'9\') ret += (c - \'0\') / (div *= 10);\n        if (neg) return -ret;\n        return ret;\n    }\n\n    private void fillBuffer() throws IOException {\n        bytesRead = din.read(buffer, bufferPointer = 0, BUFFER_SIZE);\n        if (bytesRead == -1) buffer[0] = -1;\n    }\n\n    private byte read() throws IOException {\n        if (bufferPointer == bytesRead) fillBuffer();\n        return buffer[bufferPointer++];\n    }\n\n    public void close() throws IOException {\n        if (din == null) return;\n        din.close();\n    }\n}\n\n','code','Compile Error','Time Limit Exceeded','Runtime Error','Internal error','A',2),(2229,'What will be the output of the following C code?