            }\n            } else if(t.charAt(i) == \'R\'){\n                if(lft < W){\n                    lft++;\n                }\n            }\n        }\n        return true;\n    }\n    \n    boolean okByUD(){\n        int up = x, down = x;\n        for(int i = 0; i < n; i++){\n            if(s.charAt(i) == \'U\'){\n                up--;\n            } else if(s.charAt(i) == \'D\'){\n                down++;\n            }\n            //---\n            if(up < 1 || down > H){\n                return false;\n            }\n            //---\n            if(t.charAt(i) == \'U\'){\n                if(down > 1){\n                    down--;\n                }\n            } else if(t.charAt(i) == \'D\'){\n                if(up < H){\n                    up++;\n                }\n            }\n        }\n        return true;\n    }\n    \n    void run() throws IOException {\n        Reader in = new Reader();\n        H = in.nextInt();\n        W = in.nextInt();\n        n = in.nextInt();\n        x = in.nextInt();\n        y = in.nextInt();\n        s = in.readLine();\n        t = in.readLine();\n        \n        if(okByUD() == false || okByLR() == false){\n            System.out.println(\"NO\");\n        } else {\n            System.out.println(\"YES\");\n        }\n    }\n    \n    public static void main(String[] args) throws IOException {\n        new Main().run();\n    }\n    \n    static class Reader {\n        final private int bufferSize = 1 << 16;\n        final private DataInputStream din;\n        final private byte[] buffer;\n        private int bufferPointer, bytesRead;\n        \n        public Reader(){\n            din = new DataInputStream(System.in);\n            buffer = new byte[bufferSize];\n            bufferPointer = bytesRead = 0;\n        }\n        \n        public Reader(String fileName) throws IOException {\n            din = new DataInputStream(new FileInputStream(fileName));\n            buffer = new byte[bufferSize];\n            bufferPointer = bytesRead = 0;\n        }\n        \n        private void fillBuffer() throws IOException {\n            bytesRead = din.read(buffer, bufferPointer = 0, bufferSize);\n            if(bytesRead == -1){\n                buffer[0] = -1;\n            }\n        }\n        \n        private byte read() throws IOException {\n            if(bufferPointer == bytesRead){\n                fillBuffer();\n            }\n            return buffer[bufferPointer++];\n        }\n        \n        private void close() throws IOException {\n            if(din == null){\n                return ;\n            }\n            din.close();\n        }\n        \n        public String readLine() throws IOException {\n            byte[] buf = new byte[200005];\n            int cnt = 0, c;\n            while((c = read()) != -1){\n                if(c == \'\\n\'){\n                    break;\n                }\n                buf[cnt++] = (byte)c;\n            }\n            return new String(buf, 0, cnt);\n        }\n        \n        public int nextInt() throws IOException { \n            int ret = 0; \n            byte c = read(); \n            while (c <= \' \') c = read(); \n            boolean neg = (c == \'-\'); \n            if (neg) \n                c = read();\n            do{ \n                ret = ret * 10 + c - \'0\'; \n            } while ((c = read()) >= \'0\' && c <= \'9\'); \n            if (neg) \n                return -ret; \n            return ret; \n        }\n        \n        public long nextLong() throws IOException { \n            long ret = 0; \n            byte c = read(); \n            while (c <= \' \') c = read(); \n            boolean neg = (c == \'-\'); \n            if (neg) \n                c = read(); \n            do { \n                ret = ret * 10 + c - \'0\'; \n            } while ((c = read()) >= \'0\' && c <= \'9\'); \n            if (neg) \n                return -ret; \n            return ret; \n        }\n        \n        public double nextDouble() throws IOException { \n            double ret = 0, div = 1; \n            byte c = read(); \n            while (c <= \' \') c = read(); \n            boolean neg = (c == \'-\'); \n            if (neg) \n                c = read(); \n            do { \n                ret = ret * 10 + c - \'0\'; \n            } \n            while ((c = read()) >= \'0\' && c <= \'9\'); \n            if (c == \'.\'){\n                while ((c = read()) >= \'0\' && c <= \'9\'){ \n                    ret += (c - \'0\') / (div *= 10); \n                } \n            }\n            if (neg) \n                return -ret; \n            return ret; \n        } \n    }\n}\n','code','Runtime Error','Internal error','No abnormally found','Memory Limit Exceeded','C',2),(2354,'Given a code snippet below, which behavior most likely to occur when execute it?\nimport java.util.Scanner;\npublic class Main {\n	public static void main(String[] args) {\n		Scanner sc = new Scanner(System.in);\n		int n = Integer.parseInt(sc.next());\n		int[] p = new int[n + 1];\n		for (int i = 1; i <= n; i++)\n			p[Integer.parseInt(sc.next())] = i;\n		int max = 1;\n		int tem = 1;\n		for (int i = 2; i <= n; i++) {\n			if (p[i] < p[i - 1])\n				tem = 1;\n			else\n				tem++;\n			max = Math.max(max, tem);\n		}\n		System.out.println(n - max);\n	}\n}','code','Memory Limit Exceeded','Runtime Error','No abnormally found','Time Limit Exceeded','C',2),(2355,'A relational schema for a train reservation database is given below.\rPassenger (pid, pname, age)\rReservation (pid, class, tid)  Table: Passenger\r\npid   pname   age\r\n-----------------\r\n 0    Sachin   65\r\n 1    Rahul    66\r\n 2    Sourav   67\r\n 3    Anil     69\r\n\r\nTable : Reservation\r\npid  class  tid\r\n---------------\r\n 0    AC   8200\r\n 1    AC   8201\r\n 2    SC   8201\r\n 5    AC   8203\r\n 1    SC   8204\r\n 3    AC   8202\r\nWhat pids are returned by the following SQL query for the above instance of the tables?\r\nSLECT pid\r\nFROM Reservation ,\r\nWHERE class ‘AC’ AND\r\n    EXISTS (SELECT *\r\n       FROM Passenger\r\n       WHERE age > 65 AND\r\n       Passenger. pid = Reservation.pid)','code','1, 0','1, 2','1, 3','1, 5','C',5),(2356,'Which inbuilt function in PHP is used to sort the element in Descending order?','code','sort()','asort()','dsort()','rsort()','D',3),(2357,'Select the \\\'False\\\' statement from the following statements about Normal Forms:','code','Lossless preserving decomposition into 3NF is always possible','Lossless preserving decomposition into BCNF is always possible','Any Relation with two attributes is in BCNF','BCNF is stronger than 3NF','B',7),(2358,'The relation schemas R1 and R2 form a Lossless join decomposition of R if and only if:\r(a) R1 ∩ R2 ↠ (R1 - R2)\r(b) R1 → R2\r(c) R1 ∩ R2 ↠ (R2 - R1 )\r(d)(R2 → R1) ∩ R2','code','(a) and (b) happens','(a) and (d) happens','(a) and (c) happens','(b) and (c) happens','C',5),(2359,'Look at the problem below, the solution is missing a part, which option is the most likely to complete the solution and achieve the desired goal?\n\nProblem description: You are given two 0-indexed integer arrays servers and tasks of lengths n​​​​​​ and m​​​​​​ respectively. servers[i] is the weight of the i​​​​​​th​​​​ server, and tasks[j] is the time needed to process the j​​​​​​th​​​​ task in seconds. Tasks are assigned to the servers using a task queue. Initially, all servers are free, and the queue is empty. At second j, the jth task is inserted into the queue (starting with the 0th task being inserted at second 0). As long as there are free servers and the queue is not empty, the task in the front of the queue will be assigned to a free server with the smallest weight, and in case of a tie, it is assigned to a free server with the smallest index. If there are no free servers and the queue is not empty, we wait until a server becomes free and immediately assign the next task. If multiple servers become free at the same time, then multiple tasks from the queue will be assigned in order of insertion following the weight and index priorities above. A server that is assigned task j at second t will be free again at second t + tasks[j]. Build an array ans​​​​ of length m, where ans[j] is the index of the server the j​​​​​​th task will be assigned to. Return the array ans​​​​.\n\nIncomplete Solution:\nclass Solution:\n  def assignTasks(self, servers: List[int], tasks: List[int]) -> List[int]:\n    ans = []\n    free = []  \n    used = []  \n\n    for i, weight in enumerate(servers):\n      heapq.heappush(free, (weight, i, 0))\n\n    for i, executionTime in enumerate(tasks):  \n      _______________\n      while used and used[0][0] <= i:\n        curr = heapq.heappop(used)\n        heapq.heappush(free, (curr[1], curr[2], curr[0]))\n      if free:\n        curr = heapq.heappop(free)\n        ans.append(curr[1])\n        heapq.heappush(used, (i + executionTime, curr[0], curr[1]))\n      else:\n        curr = heapq.heappop(used)\n        ans.append(curr[2])\n        heapq.heappush(used, (curr[0] + executionTime, curr[1], curr[2]))\n\n    return ans','code','      while used and used[0][0] < i + 1:','      while used and used[0][0] <= i - 1:','      while used and used[0][0] <= i:','      while used and used[0][0] < i:','C',6),(2360,'What is the value of following recurrence.T(n) = T(n/4) + T(n/2) + cn2\nT(1) = c\nT(0) = 0\nWhere c is a positive constant','code','O(n3)','O(n2)','O(n2 Logn)','O(nLogn)','B',5),(2361,'Which of the following statements are TRUE?\r\r(S1)  TCP handles both congestion and flow control\r(S2)  UDP handles congestion but not flow control\r(S3)  Fast retransmit deals with congestion but not flow control\r(S4)  Slow start mechanism deals with both congestion and flow control','code','S1, S2 and S3 only','S1 and S3 only','S3 and S4 only','S1, S3 and S4 only','B',5),(2362,'How does \"Stress Testing\" contribute to software quality assurance?','code','By optimizing code for better performance','By assessing the software\'s behavior under varying workloads','By focusing solely on manual testing','By ignoring potential risks in the software','B',5),(2363,'Given a code snippet below, which behavior most likely to occur when execute it?\npackage abc.n157.d;\n\nimport java.util.ArrayList;\nimport java.util.HashSet;\nimport java.util.List;\nimport java.util.Scanner;\nimport java.util.Set;\n\npublic class Main {\n\n	public static void main(String[] args) {\n		Scanner scanner = new Scanner(System.in);\n\n		final int N = scanner.nextInt();\n		final int M = scanner.nextInt();\n		final int K = scanner.nextInt();\n\n		List<Integer>[] friendLists = new ArrayList[N];\n\n		List<int[]> blockLists = new ArrayList<>();\n\n		for (int i = 0; i < N; i++) {\n			friendLists[i] = new ArrayList<Integer>();\n		}\n		int[] result = new int[N];\n\n		int A, B;\n		for (int i = 0; i < M; i++) {\n			A = scanner.nextInt() - 1;\n			B = scanner.nextInt() - 1;\n			friendLists[A].add(B);\n			friendLists[B].add(A);\n		}\n		for (int i = 0; i < K; i++) {\n			A = scanner.nextInt() - 1;\n			B = scanner.nextInt() - 1;\n			blockLists.add(new int[] { A, B });\n		}\n\n		boolean[] visited = new boolean[N];\n\n		Set<Integer> group = new HashSet<Integer>();\n\n		int groupCount = -1;\n		int[] root = new int[N];\n\n		for (int i = 0; i < N; i++) {\n			if (!visited[i]) {\n				groupCount++;\n				group.clear();\n				DFS(friendLists, i, visited, group);\n				for (int j : group) {\n					root[j] = groupCount;\n					result[j] = group.size() - friendLists[j].size() - 1;\n				}\n			}\n		}\n\n		for (int[] block : blockLists) {\n			if (root[block[0]] == root[block[1]]) {\n				result[block[0]]--;\n				result[block[1]]--;\n			}\n		}\n\n		String outString = \"\";\n\n		for (int i : result) {\n			outString += i + \" \";\n		}\n		System.out.println(outString);\n\n	}\n\n	static void DFS(List<Integer>[] graph, int vertex, boolean[] visited, Set<Integer> reachable) {\n		visited[vertex] = true;\n		reachable.add(vertex);\n		graph[vertex].forEach(neighbor -> {\n			if (!visited[neighbor]) {\n				DFS(graph, neighbor, visited, reachable);\n			}\n		});\n	}\n\n}\n','code','Memory Limit Exceeded','No abnormally found','Runtime Error','Time Limit Exceeded','C',2),(2364,'Given a code snippet below, which behavior most likely to occur when execute it?\nn,m=[int(i) for i in input().split()]\na=[input() for i in range(n)]\nb=[input() for i in range(m)]\nfor i in range(m):\n    for j in range(len(b[i])):\n        if b[i][j]!=a[i][j]:\n            result=True\n            break\nprint(\"No\" if result else \"Yes\")','code','Memory Limit Exceeded','No abnormally found','Time Limit Exceeded','Runtime Error','D',5),(2365,'Which plugin is used to cycle through elements, like a slideshow?','code','Carousel','Orbit','Scrollspy','Slideshow','A',5),(2366,'What is the worst case time complexity of inserting n elements into an empty linked list, if the linked list needs to be maintained in sorted order ?','code','Θ(n)','Θ(n log n)','Θ(n2)','Θ(1)','C',5),(2367,'The implementation below is producing incorrect results. \nWhich solution below correctly identifies the bug and repairs it to achieve the desired goal?\n1 import java.util.*;\n2 public class DETECT_CYCLE {\n3     public static boolean detect_cycle(Node node) {\n4         Node hare = node;\n5         Node tortoise = node;\n6         while (true) {\n7             if (hare.getSuccessor() == null)\n8                 return false;\n9             tortoise = tortoise.getSuccessor();\n10             hare = hare.getSuccessor().getSuccessor();\n11             if (hare == tortoise)\n12                 return true;\n13         }\n14     }\n15 }','code','Modify line 6:\n```           if (null==hare ||hare.getSuccessor() == null)```\n','Modify line 8:\n```return false;```','Modify line 6:\n```        while (hare != null && hare.getSuccessor() != null) {```','Modify line 7:\n```if (hare == null || hare.getSuccessor() == null)```','A',6),(2368,'Which solution below is the most likely completion the following \ncode snippet to achieve the desired goal?\n\ndef check_if_last_char_is_a_letter(txt):\n    \'\'\'\n    Create a function that returns True if the last character\n    of a given string is an alphabetical character and is not\n    a part of a word, and False otherwise.\n    Note: \"word\" is a group of characters separated by space.\n\n    Examples:\n    check_if_last_char_is_a_letter(\"apple pie\") ➞ False\n    check_if_last_char_is_a_letter(\"apple pi e\") ➞ True\n    check_if_last_char_is_a_letter(\"apple pi e \") ➞ False\n    check_if_last_char_is_a_letter(\"\") ➞ False \n    \'\'\'\n','code','    check = txt.split(\' \')[0]\n    return True if len(check) == 1 and (97 <= ord(check[-1].lower()) <= 122) else False ','    check = txt.split(\' \')[-1]\n    return True if len(check) == 1 else False ',' \n    check = txt.split(\' \')[-1]\n    return True if len(check) == 1 and (97 <= ord(check.lower()) <= 122) else False\n','    check = txt.split(\' \')[-1]\n    return True if len(check) > 0 and (97 <= ord(check[0].lower()) <= 122) else False  ','C',6),(2369,'Given a code snippet below, which behavior most likely to occur when execute it?\nimport java.util.*;\npublic class Main {\n    public static void main(String args[]) {\n        Scanner in=new Scanner(System.in);\n        int n=in.nextInt(),m=1000000000+7;\n        long arr[]=new long[n];\n        for(int i=0;i<n;i++)\n            arr[i]=in.nextLong();\n        long ans=0;\n        \n        for(int i=0;i<n;i++){\n            for(int j=i+1;j<n;j++){\n                ans=((ans%m)+(arr[i]*arr[j])%m)%m;\n            }\n        }\n        System.out.println(ans);\n    }\n}','code','Memory Limit Exceeded','Runtime Error','Compile Error','Time Limit Exceeded','D',2),(2370,'Look at the problem below, the solution is missing a part, which option is the most likely to complete the solution and achieve the desired goal?\n\nProblem description: Given an integer array nums, return the number of triplets chosen from the array that can make triangles if we take them as side lengths of a triangle.\n\nIncomplete Solution:\nclass Solution:\n  def triangleNumber(self, nums: List[int]) -> int:\n    ans = 0\n\n    nums.sort()\n\n    for k in range(len(nums) - 1, 1, -1):\n      i = 0\n      j = k - 1\n      while i < j:\n        _______________\n        if nums[i] + nums[j] > nums[k]:\n          ans += j - i\n          j -= 1\n        else:\n          i += 1\n\n    return ans','code','        if nums[i] + nums[j] >= nums[k]:','        if nums[i] + nums[k] > nums[j]:','        if nums[i] + nums[j] > nums[k]:','        if nums[j] + nums[k] > nums[i]:','C',6),(2371,'The TCP sliding window','code','can be used to control the flow of information','always occurs when the field value is 0','always occurs when the field value is 1','occurs horizontally','A',5),(2372,'What would be the current working directory at the end of the following command sequence?\n $ pwd\n /home/user1/proj\n $ cd  src\n $ cd  generic\n $ cd  .\n $ pwd','code','/home/user1/proj','/home/user1/proj/src','/home/user1','/home/user1/proj/src/generic','C',5),(2373,'Which solution below is the most likely completion the following \ncode snippet to achieve the desired goal?\n\n\ndef fizz_buzz(n: int):\n    \"\"\"Return the number of times the digit 7 appears in integers less than n which are divisible by 11 or 13.\n    >>> fizz_buzz(50)\n    0\n    >>> fizz_buzz(78)\n    2\n    >>> fizz_buzz(79)\n    3\n    \"\"\"\n','code','    ns = []\n    for i in range(n):\n        if i % 11 == 0 or i % 13 == 0:\n            ns.append(i)\n    s = \'\'.join(list(map(str, ns)))\n    ans = 0\n    for c in s:\n        ans += int(c) \n    return ans','    ns = []\n    for i in range(n):\n        if i % 10 == 0 or i % 13 == 0:\n            ns.append(i)\n    s = \'\'.join(list(map(str, ns)))\n    ans = 0\n    for c in s:\n        ans += (c == \'7\')\n    return ans','    ns = []\n    for i in range(n):\n        if i % 11 == 0 or i % 13 == 0:\n            ns.append(i)\n    s = \'\'.join(list(map(str, ns)))\n    ans = 0\n    for c in s:\n        ans += (c == \'7\')\n    return ans\n','    ns = []\n    for i in range(n-1):\n        if i % 11 == 0 or i % 13 == 0:\n            ns.append(i)\n    s = \'\'.join(list(map(str, ns)))\n    ans = 0\n    for c in s:\n        ans += (c == \'7\')\n    return ans','C',6),(2374,'Given a code snippet below, which behavior most likely to occur when execute it?\nfrom math import gcd\n\nn = int(input())\na = list(map(int,input().split()))\nb = list(map(int,input().split()))\n\nclass Seg_min():\n    def __init__(self,x):\n        #####単位元######\n        self.ide_ele_min = 10**10\n        self.func = min\n\n        self.n = len(x)\n\n        #num_max:n以上の最小の2のべき乗\n        self.num_max =2**(self.n-1).bit_length()\n        self.x = [self.ide_ele_min]*2*self.num_max\n\n        for i,num in enumerate(x, self.num_max):\n            self.x[i] = num\n        for i in range(self.num_max-1,0,-1):\n            self.x[i] = self.func(self.x[i<<1],self.x[(i<<1) + 1])\n\n    def update(self,i,x):\n        i += self.num_max\n        self.x[i] = x\n        while(i>0):\n            i = i//2\n            self.x[i] = self.func(self.x[i<<1],self.x[(i<<1) + 1])\n\n    def query(self,i,j):\n        res = self.ide_ele_min\n        if i>=j:\n            return res\n        i += self.num_max\n        j += self.num_max -1\n        while(i<=j):\n            if(i==j):\n                res = self.func(res,self.x[i])\n                break\n            if(i&1):\n                res = self.func(res,self.x[i])\n                i += 1\n            if(not j&1):\n                res = self.func(res,self.x[j])\n                j -= 1\n            i = i>>1\n            j = j>>1\n        return res\n\n\nclass Seg_max():\n    def __init__(self,x):\n        #####単位元######\n        self.ide_ele_min = 10**10 * -1\n        self.func = max\n\n        self.n = len(x)\n\n        #num_max:n以上の最小の2のべき乗\n        self.num_max =2**(self.n-1).bit_length()\n        self.x = [self.ide_ele_min]*2*self.num_max\n\n        for i,num in enumerate(x, self.num_max):\n            self.x[i] = num\n        for i in range(self.num_max-1,0,-1):\n            self.x[i] = self.func(self.x[i<<1],self.x[(i<<1) + 1])\n\n    def update(self,i,x):\n        i += self.num_max\n        self.x[i] = x\n        while(i>0):\n            i = i//2\n            self.x[i] = self.func(self.x[i<<1],self.x[(i<<1) + 1])\n\n    def query(self,i,j):\n        res = self.ide_ele_min\n        if i>=j:\n            return res\n        i += self.num_max\n        j += self.num_max -1\n        while(i<=j):\n            if(i==j):\n                res = self.func(res,self.x[i])\n                break\n            if(i&1):\n                res = self.func(res,self.x[i])\n                i += 1\n            if(not j&1):\n                res = self.func(res,self.x[j])\n                j -= 1\n            i = i>>1\n            j = j>>1\n        return res\n\n# aの最大値のindexを取得\nmax_ind = 0\nmax_num = -1\nfor ind,i in enumerate(a):\n    if(i > max_num):\n        max_ind = ind\n        max_num = i\n\n# max_ind が先頭になるように順番を変更\na = a[max_ind:] + a[:max_ind]\nb = b[max_ind:] + b[:max_ind]\n\n# Aiが小さい順に探索する。その順番を取得しておく。\norder = [(i,ind) for ind,i in enumerate(a)]\norder.sort()\n\n# 累積和を作る。\n# cs1は普通のBiの累積和\n# cs2はi*Biの累積和\ncs1_l = [0] * (n)\ncs2_l = [0] * (n)\ncs1_r = [0] * (n+1)\ncs2_r = [0] * (n+1)\n\nfor i in range(1,n):\n    cs1_l[i] = cs1_l[i-1] + b[i]\n    cs2_l[i] = cs2_l[i-1] + b[i]*i\n\nfor i in range(1,n):\n    cs1_r[-(i+1)] = cs1_r[-i] + b[-i]\n    cs2_r[-(i+1)] = cs2_r[-i] + b[-i]*i\n\n# 1週して戻ってくる点を追加しておく\na.append(a[0])\nb.append(b[0])\n\n# ゲームを終了する位置を記録・取得するためにセグ木を使う\nseg_left = Seg_max( list(range(n+1)) )\nseg_right = Seg_min( list(range(n+1)) )\n\n# すべての点について、終了するかしないかを記録しておく。\nend = [1] * (n+1)\n# end[0] = 1\n# end[-1] = 1\n\n# 終了しない場合の期待値計算の関数\ndef calc_ex(ind):\n    left = seg_left.query(0,ind)\n    right = seg_right.query(ind+1,n+1)\n\n    div = right - left\n    wid_l = ind-left\n    wid_r = right-ind\n    # left-ind\n    base = cs2_l[ind] - cs2_l[left] - (cs1_l[ind] - cs1_l[left])*left\n    ex_l = base*2 * wid_r\n\n    # ind-right\n    base = cs2_r[ind] - cs2_r[right] - (cs1_r[ind] - cs1_r[right])*(n-right)\n    ex_r = base*2 * wid_l\n\n    ex = -ex_l - ex_r + b[ind]*wid_l*wid_r*2 + a[left]*wid_r + a[right]*wid_l\n\n    return ex,div\n\n\n# Aiが大きい順に期待値計算をして、終了するかどうか判断。\n# A0は絶対に終了すべきなのでskip\norder = [j for i,j in order]\nflag = True\nwhile(flag):\n    flag = False\n    next = []\n    for ind in order:\n        if(ind==0):\n            continue\n\n        ex,div = calc_ex(ind)\n        if(a[ind]*div < ex):\n            end[ind] = 0\n            seg_left.update(ind,0)\n            seg_right.update(ind,n)\n            flag = True\n        else:\n            next.append(ind)\n    order = next[::]\n\n\n# 終了すべきポイントがわかったので期待値合計を計算\nans = [0] * (n)\nfor ind,flag in enumerate(end[:-1]):\n    if(flag==1):\n        ans[ind] = (a[ind],1)\n    else:\n        ex,div = calc_ex(ind)\n        ans[ind] = (ex,div)\n\nlcm = 1\nfor ex,div in ans:\n    lcm = (lcm*div)//gcd(lcm,div)\n\nans_num = 0\nfor ex,div in ans:\n    ans_num += ex*(lcm//div)\n\nprint(ans_num/(lcm*n))','code','Time Limit Exceeded','Compile Error','Memory Limit Exceeded','Internal error','A',6),(2375,'A semaphore has atomic operations that are known as –','code','stop() and wait()','wait() and signal()','test() and set()','None of the above','A',5),(2376,'Consider the following tables :\r\r\r\rWhat will be the output of following SQL query ?\r\r\nSELECT * FROM EMPLOYEE E    \r\nWHERE 2 = (SELECT COUNT(DISTINCT E1.SALARY)    \r\nFROM EMPLOYEE E1    \r\nWHERE E1.SALARY>E.SALARY)','code','Second highest salary','Two distinct salary of employees','Third highest salary','Employee with  second highest salary','C',7),(2377,'What will be the output of the following Python code?\nimport turtle\nt=turtle.Pen()\nt