ile((c=read())!=-1&&(c==\' \'||c==\'\\n\'||c==\'\\r\'));\n			StringBuilder s = new StringBuilder();\n			while (c != -1)\n			{\n				if (c == \' \' || c == \'\\n\'||c==\'\\r\')\n					break;\n				s.append((char)c);\n				c=read();\n			}\n			return s.toString();\n		}\n		public String nextLine() {\n			int c;\n			while((c=read())!=-1&&(c==\' \'||c==\'\\n\'||c==\'\\r\'));\n			StringBuilder s = new StringBuilder();\n			while (c != -1)\n			{\n				if (c == \'\\n\'||c==\'\\r\')\n					break;\n				s.append((char)c);\n				c = read();\n			}\n			return s.toString();\n		}\n		public int nextInt() {\n			int ret = 0;\n			byte c = read();\n			while (c <= \' \')\n				c = read();\n			boolean neg = (c == \'-\');\n			if (neg)\n				c = read();\n			do\n				ret = ret * 10 + c - \'0\';\n			while ((c = read()) >= \'0\' && c <= \'9\');\n\n			if (neg)\n				return -ret;\n			return ret;\n		}\n		public int[] readIntArray(int n) {\n			int[] ar = new int[n];\n			for(int i=0; i<n; ++i)\n				ar[i]=nextInt();\n			return ar;\n		}\n		public long nextLong() {\n			long ret = 0;\n			byte c = read();\n			while (c <= \' \')\n				c = read();\n			boolean neg = (c == \'-\');\n			if (neg)\n				c = read();\n			do\n				ret = ret * 10 + c - \'0\';\n			while ((c = read()) >= \'0\' && c <= \'9\');\n			if (neg)\n				return -ret;\n			return ret;\n		}\n		public long[] readLongArray(int n) {\n			long[] ar = new long[n];\n			for(int i=0; i<n; ++i)\n				ar[i]=nextLong();\n			return ar;\n		}\n		public double nextDouble() {\n			double ret = 0, div = 1;\n			byte c = read();\n			while (c <= \' \')\n				c = read();\n			boolean neg = (c == \'-\');\n			if (neg)\n				c = read();\n			do\n				ret = ret * 10 + c - \'0\';\n			while ((c = read()) >= \'0\' && c <= \'9\');\n			if (c == \'.\')\n				while ((c = read()) >= \'0\' && c <= \'9\')\n					ret += (c - \'0\') / (div *= 10);\n			if (neg)\n				return -ret;\n			return ret;\n		}\n		private void fillBuffer() throws IOException {\n			bytesRead = din.read(buffer, bufferPointer = 0, BUFFER_SIZE