 Singh\n */\npublic class Main {\n    public static void main(String[] args) {\n        InputStream inputStream = System.in;\n        OutputStream outputStream = System.out;\n        InputReader in = new InputReader(inputStream);\n        PrintWriter out = new PrintWriter(outputStream);\n        EGetEverything solver = new EGetEverything();\n        solver.solve(1, in, out);\n        out.close();\n    }\n\n    static class EGetEverything {\n        long INF = (long) 1e14 + 1;\n        int MAXN = 1005;\n        PrintWriter out;\n        InputReader in;\n        int n;\n        int m;\n        int[] masks = new int[MAXN];\n        long[] cost = new long[MAXN];\n        int MAX_MSK = (1 << 12);\n        long[][] dp = new long[MAXN][MAX_MSK];\n\n        long go(int ind, int mask) {\n            if (ind == m) {\n                if (mask == (1 << n) - 1)\n                    return 0;\n                else\n                    return INF;\n            }\n            long mn = INF;\n            mn = Math.min(go(ind + 1, mask), mn);\n            mn = Math.min(go(ind + 1, mask | masks[ind]) + cost[ind], mn);\n            dp[ind][mask] = mn;\n            return mn;\n        }\n\n        public void solve(int testNumber, InputReader in, PrintWriter out) {\n            this.out = out;\n            this.in = in;\n            n = ni();\n            m = ni();\n            int i = 0;\n            for (i = 0; i < m; i++) {\n                cost[i] = nl();\n                int x = ni();\n                for (int j = 0; j < x; j++)\n                    masks[i] |= (1 << (ni() - 1));\n            }\n            for (i = 0; i < MAXN; i++)\n                Arrays.fill(dp[i], -1);\n            long ans = go(0, 0);\n            if (ans == INF)\n                pn(-1);\n            else\n                pn(ans);\n        }\n\n        int ni() {\n            return in.nextInt();\n        }\n\n        long nl() {\n            return in.nextLong();\n        }\n\n        void pn(long zx) {\n            out.println(zx);\n        }\n\n    }\n\n    static class InputReader {\n        private InputStream stream;\n        private byte[] buf = new byte[1024];\n        private int curChar;\n        private int numChars;\n\n        public InputReader(InputStream stream) {\n            this.stream = stream;\n        }\n\n        public int read() {\n            if (numChars == -1) {\n                throw new UnknownError();\n            }\n            if (curChar >= numChars) {\n                curChar = 0;\n                try {\n                    numChars = stream.read(buf);\n                } catch (IOException e) {\n                    throw new UnknownError();\n                }\n                if (numChars <= 0) {\n                    return -1;\n                }\n            }\n            return buf[curChar++];\n        }\n\n        public int nextInt() {\n            return Integer.parseInt(next());\n        }\n\n        public long nextLong() {\n            return Long.parseLong(next());\n        }\n\n        public String next() {\n            int c = read();\n            while (isSpaceChar(c)) {\n                c = read();\n            }\n            StringBuffer res = new StringBuffer();\n            do {\n                res.appendCodePoint(c);\n                c = read();\n            } while (!isSpaceChar(c));\n\n            return res.toString();\n        }\n\n        private boolean isSpaceChar(int c) {\n            return c == \' \' || c == \'\\n\' || c == \'\\r\' || c == \'\\t\' || c == -1;\n        }\n\n    }\n}\n\n','code','Runtime Error','Time Limit Exceeded','Internal error','Memory Limit Exceeded','B',2),(2975,'Which SQL operator is used to test for negation?','code','NOT','EXISTS','IS','!=','A',5),(2976,'Given a code snippet below, which behavior most likely to occur when execute it?\nX, K, D = map(int, input().split())\n\nfor k in range(K):\n    if min(abs(X+D), abs(X-D)) < abs(X):\n        X = min(abs(X+D), abs(X-D))\n        K -= 1\n    else:\n        if K%2 == 0:\n            print(X)\n            break\n        else:\n            X = min(abs(X+D), abs(X-D))\n            print(X)\n            break\n\nif K == 0:\n    print(X)\n','code','Time Limit Exceeded','Internal error','No abnormally found','Runtime Error','A',5),(2977,'Given a code snippet below, which behavior most likely to occur when execute it?\nimport math\nN = int(input())\nx = [0 for i in range(N)]\ny = [0 for i in range(N)]\nfor i in range(N):\n    x[i], y[i] = map(int, input().split())\n\n\ndef mindis(p, q):\n    j = 0\n    for i in range(N):\n        if (x[i]-p)**2+(y[i]-q)**2<(x[j]-p)**2+(y[j]-q)**2:\n            j = i\n    return j\n\n\nr = [0 for i in range(N)]\nM = 19*10**5\nfor i in range(M):\n    c = math.cos(2*math.pi*i/M)*10**10\n    s = math.sin(2*math.pi*i/M)*10**10\n    k = mindis(c, s)\n    r[k] += 1\nS = sum(r)\nfor i in range(N):\n    print(r[i]/S)\n','code','Runtime Error','Time Limit Exceeded','No abnormally found','Compile Error','B',6),(2978,'The cyclomatic complexity of each of the modules A and B shown below is 10. What is the cyclomatic complexity of the sequential integration shown on the right hand side?','code','19','21','20','10','A',5),(2979,'Given below are several usages of the anchor tag in HTML.\r  <A HREF = \"http://www.gate.ac.in/HTML/BASIC/testpage.html\">Test Me</A>   <A HREF = \"/BASIC/testpage.html\">Test Me</A>   <A HREF = \"testpage.html\">Test Me</A>   <A HREF = \"testpage.html#test\">Test Me</A>  \rWhich of the above are valid?','code','I and II only','I and III only','I, II and III only','I, II, III and IV','D',5),(2980,'The relation book (title, price) contains the titles and prices of different books. Assuming that no two books have the same price, what does the following SQL query list?\r\r\n  select title\r\n  from book as B\r\n  where (select count(*)\r\n     from book as T\r\n     where T.price > B.price) < 5','code','Titles of the four most expensive books','Title of the fifth