nt W;\n	static int Dh;\n	static int Dw;\n	static char[][] S;\n\n	public static void main(String[] args) throws IOException {\n\n		Scanner sc = new Scanner(System.in);\n		int H = sc.nextInt();\n		int W = sc.nextInt();\n		int M = sc.nextInt();\n\n		int[] h = new int[H];\n		int[] w = new int[W];\n		HashSet<String> exists = new HashSet<>();\n\n		for(int i = 0;i<M ; i++) {\n			int nowH =sc.nextInt()-1;\n			int nowW =sc.nextInt()-1;\n			h[nowH]++;\n			w[nowW]++;\n			String now =nowH+\",\"+nowW;\n			exists.add(now);\n		}\n\n		int maxH = 0;\n		int maxW = 0;\n		List<Integer> selectedH = new ArrayList<Integer>();\n		List<Integer> selectedW = new ArrayList<Integer>();\n\n		for(int i = 0;i<H ; i++) {\n			if(maxH < h[i] ) {\n				maxH = h[i];\n				selectedH.clear();\n				selectedH.add(i);\n			}else if(maxH == h[i]) {\n				selectedH.add(i);\n			}\n		}\n		for(int i = 0;i<W ; i++) {\n			if(maxW < w[i] ) {\n				maxW = w[i];\n				selectedW.clear();\n				selectedW.add(i);\n			}else if(maxW == w[i]) {\n				selectedW.add(i);\n			}\n		}\n\n		boolean allExist = true;\n\n		for(int sH:selectedH) {\n			for(int sW: selectedW) {\n				if(!exists.contains(sH+\",\"+sW)) {\n					allExist = false;\n				}\n			}\n		}\n		ans = maxH + maxW;\n\n		if(allExist) {\n			ans--;\n		}\n\n\n		System.out.println(ans);\n	}\n\n\n//	public static void walk(int nowH, int nowW, int warped) {\n//		if(nowH < 0 || nowH >= H || nowW <0 || nowW >= W || S[nowH][nowW] == \'#\' || warped >= warp[nowH][nowW]) {\n//			return;\n//		}\n//		if(nowH == Dh && nowW == Dw && ans > warped) {\n//			ans = warped;\n//		}\n//		int[] now = {nowH, nowW, warped};\n//		q.add(now);\n//		warp[nowH][nowW] = warped;\n//		for(int i = 0;i<4 ; i++) {\n//			walk(nowH+directions4[i][0], nowW+directions4[i][1], warped);\n//		}\n//	}\n	//	public static void warp(int nowH, int nowW, int warped) {\n	//\n	//\n	//\n	//\n	//	}\n\n	//素数判定\n	public static boolean isPrime(long num) {\n		if (num < 2) return false;\n		else if (num == 2) return true;\n		else if (num % 2 == 0) return false; // 偶数はあらかじめ除く\n\n		double sqrtNum = Math.sqrt(num);\n		for (int i = 3; i <= sqrtNum; i += 2)\n		{\n			if (num % i == 0)\n			{\n				// 素数ではない\n				return false;\n			}\n		}\n\n		// 素数である\n		return true;\n	}\n\n	//BFS用に二つの配列を足し算する\n	static int[] addArrayElms(int[] a, int[] b) {\n		int[] c = new int[a.length];\n		for(int i = 0; i < a.length; i++) {\n			c[i] = a[i] + b[i];\n		}\n		return c;\n	}\n\n	//	//二分探索\n	//k <= num となる最小の配列要素kのインデックスを返す\n	static private int binarySearch(long num, long[] orderedArray){\n		int lowerBorder = -1;\n		int upperBorder = orderedArray.length;\n		int mid;\n\n		while(upperBorder - lowerBorder >1) {\n			mid = (upperBorder + lowerBorder)/2;\n			if(orderedArray[mid]<=num) {\n				lowerBorder = mid;\n			}else {\n				upperBorder = mid;\n			}\n		}\n		return lowerBorder;\n	}\n\n	//二分探索\n	//k <= num となる最小のList要素kのインデックスを返す\n	static private int binarySearch(long num, ArrayList<Long> orderedList){\n		int lowerBorder = -1;\n		int upperBorder = orderedList.size();\n		int mid;\n\n		while(upperBorder - lowerBorder >1) {\n			mid = (upperBorder + lowerBorder)/2;\n			if(orderedList.get(mid)<=num) {\n				lowerBorder = mid;\n			}else {\n				upperBorder = mid;\n			}\n		}\n		return lowerBorder;\n	}\n\n	//aとbの最小公倍数を求める\n	public static int gcd(int a, int b) {\n		return b == 0 ? a: gcd(b, a % b);\n	}\n	public static long gcd(long a, long b) {\n		return b == 0 ? a: gcd(b, a % b);\n	}\n\n	//Union-Find用の配列を要素数nで初期化\n	static void ufInit(int n){\n		parent = new int[n];\n		rank = new int[n];\n	}\n\n	//Union-Findの要素の最上位の親（グループ名）を返す\n	static int ufFind(int a) {\n		if(parent[a]==a) {\n			return a;\n		}else {\n			return ufFind(parent[a]);\n		}\n	}\n\n	//Union-Find木を連結する\n	static void ufUnite(int a, int b) {\n		a = parent[a];\n		b = parent[b];\n\n		if(a==b) {\n			return;\n		}\n		if(rank[a] > rank[b]){\n			parent[b]=a;\n		}else {\n			parent[a]=b;\n			if(rank[a]==rank[b]) {\n				rank[b]++;\n			}\n		}\n	}\n\n	static boolean ufSame(int a, int b) {\n		return ufFind(a)==ufFind(b);\n	}\n}\n','code','Runtime Error','No abnormally found','Time Limit Exceeded','Memory Limit Exceeded','C',2),(3058,'Relative to the program translated by a compiler, the same program when interpreted runs','code','Faster','Slower','At the same speed','May be faster or slower','B',5),(3059,'What will be the output of the following C code?\n    #include <stdio.h>    int main()    {        int i = 10;        int *p = &i;        foo(&p);        printf(\"%d \", *p);        printf(\"%d \", *p);    }    void foo(int **const p)    {        int j = 11;        *p = &j;        printf(\"%d \", **p);    }','code','11 11 11','11 11 Undefined-value','Compile time error','Segmentation fault/code-crash','B',1),(3060,'Which class indicates uppercased text?','code','.text-capitalize','.uppercase','.text-uppercase','.ucase','C',5),(3061,'Which of the following protocols is an application layer protocol that establishes, manages and terminates multimedia sessions ?','code','Session Maintenance Protocol','Real - time Streaming Protocol','Real - time Transport Control Protocol','Session Initiation Protocol','D',5),(3062,'The address of a class B host is to be split into subnets with a 6-bit subnet number. What is the maximum number of subnets and the maximum number of hosts in each subnet?','code','62 subnets and 262142 hosts.','64 subnets and 262142 hosts.','62 subnets and 1022 hosts.','64 subnets and 1024 hosts.','C',1),(3063,'Which is NOT a valid operator in PostgreSQL?','code','AND','ILIKE','IS','LIKE','C',5),(3064,'Look at the problem below, the solution is missing a part, which option is the most likely to complete the solution and achieve the desired goal?\n\nProblem description: You are given a 0-indexed binary string s of length n on which you can apply two types of operations: Return the minimum cost to make all characters of the string equal. Invert a character means if its value is \'0\' it becomes \'1\' and vice-versa.\n\nIncomplete Solution:\nclass Solu