n            loop = true;\n            return 0;\n        }\n        seen[cur] = true;\n        long ret = 0;\n        for(int e : edge[cur]){\n            ret = f(e)+1;\n        }\n        return ret;\n    }\n\n    int[] zalgo(String s) {\n		int n = s.length();\n		int[] ret = new int[n];\n		ret[0] = n;\n		int i = 1, j = 0;\n		while (i < n) {\n			while (i + j < n && s.charAt(j) == s.charAt(i + j))\n				++j;\n			ret[i] = j;\n			if (j == 0) {\n				++i;\n				continue;\n			}\n			int k = 1;\n			while (i + k < n && k + ret[k] < j) {\n				ret[i + k] = ret[k];\n				++k;\n			}\n			i += k;\n			j -= k;\n		}\n		return ret;\n	}\n    void run() throws Exception\n    {\n        is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());\n        out = new PrintWriter(System.out);\n        long s = System.currentTimeMillis();\n        solve();\n        out.flush();\n        if(!INPUT.isEmpty())tr(System.currentTimeMillis()-s+\"ms\");\n    }\n    \n    public static void main(String[] args) throws Exception { new Main().run(); }\n    \n    private byte[] inbuf = new byte[1024];\n    private int lenbuf = 0, ptrbuf = 0;\n    \n    private int readByte()\n    {\n        if(lenbuf == -1)throw new InputMismatchException();\n        if(ptrbuf >= lenbuf){\n            ptrbuf = 0;\n            try { lenbuf = is.read(inbuf); } catch (IOException e) { throw new InputMismatchException(); }\n            if(lenbuf <= 0)return -1;\n        }\n        return inbuf[ptrbuf++];\n    }\n    \n    private boolean isSpaceChar(int c) { return !(c >= 33 && c <= 126); }\n    private int skip() { int b; while((b = readByte()) != -1 && isSpaceChar(b)); return b; }\n    \n    private double nd() { return Double.parseDouble(ns()); }\n    private char nc() { return (char)skip(); }\n    \n    private String ns()\n    {\n        int b = skip();\n        StringBuilder sb = new StringBuilder();\n        while(!(isSpaceChar(b) && b != \' \')){\n            sb.appendCodePoint(b);\n            b = readByte();\n        }\n        return sb.toString();\n    }\n    \n    private char[] ns(int n)\n    {\n        char[] buf = new char[n];\n        int b = skip(), p = 0;\n        while(p < n && !(isSpaceChar(b))){\n            buf[p++] = (char)b;\n            b = readByte();\n        }\n        return n == p ? buf : Arrays.copyOf(buf, p);\n    }\n    \n    private char[][] nm(int n, int m)\n    {\n        char[][] map = new char[n][];\n        for(int i = 0;i < n;i++)map[i] = ns(m);\n        return map;\n    }\n    \n    private int[] na(int n)\n    {\n        int[] a = new int[n];\n        for(int i = 0;i < n;i++)a[i] = ni();\n        return a;\n    }\n    \n    private int ni()\n    {\n        int num = 0, b;\n        boolean minus = false;\n        while((b = readByte()) != -1 && !((b >= \'0\' && b <= \'9\') || b == \'-\'));\n        if(b == \'-\'){\n            minus = true;\n            b = readByte();\n        }\n        \n        while(true){\n            if(b >= \'0\' && b <= \'9\'){\n                num = num * 10 + (b - \'0\');\n            }else{\n                return minus ? -num : num;\n            }\n            b = readByte();\n        }\n    }\n    \n    private long nl()\n    {\n        long num = 0;\n        int b;\n        boolean minus = false;\n        while((b = readByte()) != -1 && !((b >= \'0\' && b <= \'9\') || b == \'-\'));\n        if(b == \'-\'){\n            minus = true;\n            b = readByte();\n        }\n        \n        while(true){\n            if(b >= \'0\' && b <= \'9\'){\n                num = num * 10 + (b - \'0\');\n            }else{\n                return minus ? -num : num;\n            }\n            b = readByte();\n        }\n    }\n    \n    private static void tr(Object... o) { System.out.println(Arrays.deepToString(o)); }\n \n}\n','code','No abnormally found','Memory Limit Exceeded','Runtime Error','Compile Error','C',2),(3083,'Which below in Node.js are used to join a number of path segments ?','code','path.a